{"script":"deploy = json.decode(repo.read("deploy.json"))
overrides = repo.read("overrides.json", missing_ok = True)

prod = [t for t in deploy["targets"] if t["env"] == "prod"]
names = sorted([t["name"] for t in prod])
total = 0
for t in prod:
